/* ============================================================
   AMPH Lab — Certificate generator
   Builds a self-contained certificate (SVG background, all
   logos embedded as base64) and stamps the participant name
   onto an HTML canvas for image/PDF download.
   ============================================================ */

const LOGOS = {
  vu: { w: 83, h: 140, src: "data:image/png;base64," },
  cse: { w: 130, h: 140, src: "data:image/png;base64," },
  icsetep: { w: 140, h: 140, src: "data:image/png;base64," },
  ugc: { w: 145, h: 140, src: "data:image/png;base64," },
  adb: { w: 140, h: 140, src: "data:image/png;base64," },};

const CERT_W = 1600;
const CERT_H = 1132;

function esc(str) {
  return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/* Builds the certificate background (everything except the
   participant's name) as an SVG string. The name is drawn
   afterwards directly on the canvas so it can use a loaded
   webfont crisply at any resolution. */
function buildCertificateSVG() {
  const w = CERT_W, h = CERT_H;
  const cx = w / 2;

  const logoRow = [LOGOS.vu, LOGOS.cse, LOGOS.icsetep, LOGOS.ugc, LOGOS.adb];
  const rowH = 92;
  const gap = 46;
  const scaled = logoRow.map((l) => ({ ...l, dw: (l.w / l.h) * rowH }));
  const totalW = scaled.reduce((s, l) => s + l.dw, 0) + gap * (scaled.length - 1);
  let x = cx - totalW / 2;
  const logosSvg = scaled
    .map((l) => {
      const imgTag = `<image x="${x.toFixed(1)}" y="72" width="${l.dw.toFixed(1)}" height="${rowH}" href="${l.src}" />`;
      x += l.dw + gap;
      return imgTag;
    })
    .join("\n");

  return `
<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#fefdf9"/>
      <stop offset="100%" stop-color="#f7f2e6"/>
    </linearGradient>
    <linearGradient id="goldline" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#d7a63e" stop-opacity="0"/>
      <stop offset="50%" stop-color="#d7a63e" stop-opacity="1"/>
      <stop offset="100%" stop-color="#d7a63e" stop-opacity="0"/>
    </linearGradient>
  </defs>

  <rect width="${w}" height="${h}" fill="url(#bg)"/>

  <!-- Decorative border -->
  <rect x="26" y="26" width="${w - 52}" height="${h - 52}" fill="none" stroke="#d7a63e" stroke-width="4"/>
  <rect x="40" y="40" width="${w - 80}" height="${h - 80}" fill="none" stroke="#0d1f42" stroke-width="1.5"/>
  <circle cx="26" cy="26" r="9" fill="#d7a63e"/>
  <circle cx="${w - 26}" cy="26" r="9" fill="#d7a63e"/>
  <circle cx="26" cy="${h - 26}" r="9" fill="#d7a63e"/>
  <circle cx="${w - 26}" cy="${h - 26}" r="9" fill="#d7a63e"/>

  ${logosSvg}

  <text x="${cx}" y="200" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="19" letter-spacing="3.5" fill="#0d1f42" font-weight="700">DEPARTMENT OF CSE, VARENDRA UNIVERSITY &#8226; ICSETEP RDG SUB-PROJECT</text>

  <text x="${cx}" y="268" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-size="54" font-weight="700" letter-spacing="4" fill="#0d1f42">CERTIFICATE OF PARTICIPATION</text>
  <rect x="${cx - 130}" y="290" width="260" height="4" fill="url(#goldline)"/>

  <text x="${cx}" y="336" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="19" fill="#475467">Inception Workshop &#8226; Affordable Myoelectric Prosthetic Hand for Low-Income Amputees in Bangladesh</text>

  <text x="${cx}" y="410" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-style="italic" font-size="28" fill="#344054">This is to certify that</text>

  <!-- gap for name goes here (drawn on canvas) -->

  <line x1="${cx - 360}" y1="560" x2="${cx + 360}" y2="560" stroke="#d7a63e" stroke-width="2.5"/>

  <text x="${cx}" y="608" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="19" fill="#475467">
    <tspan x="${cx}" dy="0">has actively participated in the Inception Workshop of the ICSETEP Research &amp; Development</tspan>
    <tspan x="${cx}" dy="30">Grant Sub-Project, held at the Auditorium, Varendra University, Rajshahi on 10 August 2026,</tspan>
    <tspan x="${cx}" dy="30">organized by the Department of CSE, Varendra University.</tspan>
  </text>

  <!-- Signature blocks -->
  <line x1="200" y1="960" x2="520" y2="960" stroke="#98a2b3" stroke-width="1.5"/>
  <text x="360" y="992" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-weight="700" font-size="19" fill="#0d1f42">Md. Khademul Islam Molla, PhD</text>
  <text x="360" y="1018" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="15" fill="#667085">Vice Chancellor, Varendra University</text>

  <line x1="${cx - 160}" y1="960" x2="${cx + 160}" y2="960" stroke="#98a2b3" stroke-width="1.5"/>
  <text x="${cx}" y="992" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-weight="700" font-size="19" fill="#0d1f42">Dr. Ahammad Hossain</text>
  <text x="${cx}" y="1018" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="15" fill="#667085">Principal Investigator, ICSETEP RDG Sub-Project</text>

  <line x1="${w - 520}" y1="960" x2="${w - 200}" y2="960" stroke="#98a2b3" stroke-width="1.5"/>
  <text x="${w - 360}" y="992" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-weight="700" font-size="19" fill="#0d1f42">Shamim Ahmad</text>
  <text x="${w - 360}" y="1018" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="15" fill="#667085">Head, Department of CSE &amp; Head of URDGS</text>

  <text x="${cx}" y="1082" text-anchor="middle" font-family="Plus Jakarta Sans, Arial, sans-serif" font-size="13.5" fill="#98a2b3">This certificate is generated digitally on amphlab.vu.edu (placeholder) and does not require a physical signature.</text>
</svg>`.trim();
}

function svgToDataUrl(svgString) {
  const encoded = encodeURIComponent(svgString)
    .replace(/'/g, "%27")
    .replace(/"/g, "%22");
  return `data:image/svg+xml;charset=utf-8,${encoded}`;
}

let bgImagePromise = null;
function loadBackground() {
  if (bgImagePromise) return bgImagePromise;
  bgImagePromise = new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Could not build the certificate artwork."));
    img.src = svgToDataUrl(buildCertificateSVG());
  });
  return bgImagePromise;
}

const NAME_FONT = '"Great Vibes", "Apple Chancery", cursive';
const NAME_BASELINE_Y = 500; // sits below "This is to certify that" and above the rule line
const NAME_MAX_WIDTH = CERT_W * 0.62;
const NAME_FONT_PX = 76;

async function renderCertificate(name) {
  const bg = await loadBackground();
  try {
    await document.fonts.load(`${NAME_FONT_PX}px ${NAME_FONT}`);
    await document.fonts.ready;
  } catch (_) {
    /* non-fatal — falls back to cursive */
  }

  const canvas = document.createElement("canvas");
  canvas.width = CERT_W;
  canvas.height = CERT_H;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(bg, 0, 0, CERT_W, CERT_H);

  let fontPx = NAME_FONT_PX;
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#0d1f42";
  ctx.font = `${fontPx}px ${NAME_FONT}`;
  while (ctx.measureText(name).width > NAME_MAX_WIDTH && fontPx > 30) {
    fontPx -= 1;
    ctx.font = `${fontPx}px ${NAME_FONT}`;
  }
  ctx.fillText(name, CERT_W / 2, NAME_BASELINE_Y);

  return canvas;
}

window.AMPHCertificate = { renderCertificate };
